{"content":"#include <cstdio>
#include <cstdlib>
#include <vector>

#include "cJSON.h"
#include "lodepng.h"

static char *read_file(const char *path, size_t *out_len) {
  FILE *f = fopen(path, "rb");
  if (!f) return NULL;
  fseek(f, 0, SEEK_END);
  long n = ftell(f);
  fseek(f, 0, SEEK_SET);
  if (n < 0) {
    fclose(f);
    return NULL;
  }
  char *buf = (char *)malloc((size_t)n + 1);
  if (!buf) {
    fclose(f);
    return NULL;
  }
  size_t got = fread(buf, 1, (size_t)n, f);
  fclose(f);
  buf[got] = '\0';
  if (out_len) *out_len = got;
  return buf;
}

static int load_vector(const cJSON *arr, std::vector<double> &out) {
  if (!cJSON_IsArray(arr)) return -1;
  int n = cJSON_GetArraySize(arr);
  out.resize((size_t)n);
  for (int i = 0; i < n; i++) {
    const cJSON *v = cJSON_GetArrayItem(arr, i);
    if (!cJSON_IsNumber(v)) return -1;
    out[(size_t)i] = v->valuedouble;
  }
  return 0;
}

static int load_matrix(const cJSON *arr, std::vector<double> &out, int *rows,
                       int *cols) {
  if (!cJSON_IsArray(arr)) return -1;
  int r = cJSON_GetArraySize(arr);
  if (r <= 0) return -1;
  const cJSON *row0 = cJSON_GetArrayItem(arr, 0);
  if (!cJSON_IsArray(row0)) return -1;
  int c = cJSON_GetArraySize(row0);
  if (c <= 0) return -1;
  out.resize((size_t)r * (size_t)c);
  for (int i = 0; i < r; i++) {
    const cJSON *row = cJSON_GetArrayItem(arr, i);
    if (!cJSON_IsArray(row) || cJSON_GetArraySize(row) != c) return -1;
    for (int j = 0; j < c; j++) {
      const cJSON *v = cJSON_GetArrayItem(row, j);
      if (!cJSON_IsNumber(v)) return -1;
      out[(size_t)i * (size_t)c + (size_t)j] = v->valuedouble;
    }
  }
  *rows = r;
  *cols = c;
  return 0;
}

int main(int argc, char **argv) {
  if (argc != 3) {
    fprintf(stderr, "Usage: %s weights.json image.png\n",
            argc > 0 ? argv[0] : "cli_tool");
    return 1;
  }

  size_t json_len = 0;
  char *json_text = read_file(argv[1], &json_len);
  if (!json_text) {
    fprintf(stderr, "Error: cannot read weights file '%s'\n", argv[1]);
    return 1;
  }
  cJSON *root = cJSON_Parse(json_text);
  free(json_text);
  if (!root) {
    fprintf(stderr, "Error: invalid JSON in '%s'\n", argv[1]);
    return 1;
  }

  std::vector<double> w1, b1, w2, b2, w3, b3;
  int w1r = 0, w1c = 0, w2r = 0, w2c = 0, w3r = 0, w3c = 0;
  int ok = load_matrix(cJSON_GetObjectItemCaseSensitive(root, "input_layer.weight"),
                       w1, &w1r, &w1c) == 0 &&
           load_vector(cJSON_GetObjectItemCaseSensitive(root, "input_layer.bias"),
                       b1) == 0 &&
           load_matrix(cJSON_GetObjectItemCaseSensitive(root, "hidden_layer.weight"),
                       w2, &w2r, &w2c) == 0 &&
           load_vector(cJSON_GetObjectItemCaseSensitive(root, "hidden_layer.bias"),
                       b2) == 0 &&
           load_matrix(cJSON_GetObjectItemCaseSensitive(root, "output_layer.weight"),
                       w3, &w3r, &w3c) == 0 &&
           load_vector(cJSON_GetObjectItemCaseSensitive(root, "output_layer.bias"),
                       b3) == 0;
  cJSON_Delete(root);
  if (!ok) {
    fprintf(stderr, "Error: bad or missing weight arrays in '%s'\n", argv[1]);
    return 1;
  }
  int hidden = w1r, input_dim = w1c, classes = w3r;
  if (hidden <= 0 || input_dim <= 0 || classes <= 0 ||
      (int)b1.size() != hidden || w2r != hidden || w2c != hidden ||
      (int)b2.size() != hidden || w3c != hidden || (int)b3.size() != classes ||
      input_dim != 28 * 28) {
    fprintf(stderr, "Error: inconsistent weight shapes\n");
    return 1;
  }

  unsigned char *rgba = NULL;
  unsigned w = 0, h = 0;
  unsigned err = lodepng_decode32_file(&rgba, &w, &h, argv[2]);
  if (err) {
    fprintf(stderr, "Error: cannot decode image '%s': %s\n", argv[2],
            lodepng_error_text(err));
    return 1;
  }

  std::vector<double> x((size_t)input_dim);
  for (int y = 0; y < 28; y++) {
    for (int xx = 0; xx < 28; xx++) {
      unsigned sx = (unsigned)((double)xx * (double)w / 28.0);
      unsigned sy = (unsigned)((double)y * (double)h / 28.0);
      if (sx >= w) sx = w - 1;
      if (sy >= h) sy = h - 1;
      const unsigned char *p = rgba + (sy * w + sx) * 4;
      double grey = 0.299 * p[0] + 0.587 * p[1] + 0.114 * p[2];
      x[(size_t)y * 28 + (size_t)xx] = grey / 255.0;
    }
  }
  free(rgba);

  std::vector<double> h1((size_t)hidden), h2((size_t)hidden),
      out((size_t)classes);
  for (int i = 0; i < hidden; i++) {
    double s = b1[(size_t)i];
    for (int j = 0; j < input_dim; j++)
      s += w1[(size_t)i * (size_t)input_dim + (size_t)j] * x[(size_t)j];
    h1[(size_t)i] = s > 0.0 ? s : 0.0;
  }
  for (int i = 0; i < hidden; i++) {
    double s = b2[(size_t)i];
    for (int j = 0; j < hidden; j++)
      s += w2[(size_t)i * (size_t)hidden + (size_t)j] * h1[(size_t)j];
    h2[(size_t)i] = s > 0.0 ? s : 0.0;
  }
  int best = 0;
  for (int i = 0; i < classes; i++) {
    double s = b3[(size_t)i];
    for (int j = 0; j < hidden; j++)
      s += w3[(size_t)i * (size_t)hidden + (size_t)j] * h2[(size_t)j];
    out[(size_t)i] = s;
    if (i == 0 || s > out[(size_t)best]) best = i;
  }

  printf("%d\n", best);
  return 0;
}
